<?php
/**
 * Synced patterns: every VuloForm pattern lives in WordPress, editable in Appearance → Design → Patterns
 * (category "VuloForm"), like patterns you make yourself.
 *
 *   pattern-files/*.php   the originals (generated by src/build-patterns.py). They are NOT registered as theme
 *                         patterns, because WordPress shows theme patterns locked (read-only).
 *   On theme activation (and Appearance → VuloForm → Create synced patterns) each file becomes a synced pattern
 *   (post type wp_block), only when it doesn't exist yet. "Put the original design back" overwrites them
 *   (WordPress keeps the old version as a revision).
 *   Whole-page patterns ("Page · Home" …) are made of the section patterns, so editing "Home · Hero"
 *   changes Home everywhere it is used.
 *
 * @package VuloForm
 */

defined( 'ABSPATH' ) || exit;

/** Every pattern file: slug => [ 'title', 'description', 'file' ]. */
function vf_pattern_files() {
	static $list = null;
	if ( null === $list ) {
		$list = array();
		foreach ( (array) glob( VF_DIR . '/pattern-files/*.php' ) as $file ) {
			$head = get_file_data( $file, array( 'title' => 'Title', 'description' => 'Description' ) );
			$list[ basename( $file, '.php' ) ] = $head + array( 'file' => $file );
		}
	}
	return $list;
}

/** Block markup of a pattern file (the files echo their markup; links are resolved here). */
function vf_pattern_markup( $slug ) {
	$file = VF_DIR . '/pattern-files/' . sanitize_file_name( $slug ) . '.php';
	if ( ! file_exists( $file ) ) {
		return '';
	}
	ob_start();
	include $file;
	return trim( ob_get_clean() );
}

/** Whole pages made of section patterns (the vs-… pages are single patterns). */
function vf_pattern_pages() {
	return array(
		'page-home'    => array( 'home-hero', 'home-templates', 'home-builder', 'home-logic', 'home-features', 'home-compare', 'home-embed', 'home-privacy', 'home-faq', 'home-cta' ),
		'page-compare' => array( 'compare-hero', 'compare-tables', 'compare-links', 'get-it-banner' ),
		'page-blog'    => array( 'blog-header', 'blog-posts', 'get-it-banner' ),
	);
}

/** slug => synced pattern ID (also picks up the header/footer made by 2.0.0). */
function vf_synced_ids() {
	$ids = (array) get_option( 'vf_synced_patterns', array() );
	foreach ( array( 'site-header' => 'vf_header_block', 'site-footer' => 'vf_footer_block' ) as $slug => $old ) {
		if ( empty( $ids[ $slug ] ) && get_option( $old ) ) {
			$ids[ $slug ] = (int) get_option( $old );
		}
	}
	return $ids;
}

/** The synced pattern of a slug, or null when it was deleted / never made. */
function vf_synced_post( $slug ) {
	$ids  = vf_synced_ids();
	$post = empty( $ids[ $slug ] ) ? null : get_post( (int) $ids[ $slug ] );
	return ( $post && 'wp_block' === $post->post_type && 'trash' !== $post->post_status ) ? $post : null;
}

/** Markup that shows a synced pattern. */
function vf_pattern_ref( $id ) {
	return '<!-- wp:block {"ref":' . (int) $id . '} /-->';
}

/**
 * Make (or with $reset, put back) the synced pattern of one file. Returns its ID (0 on failure).
 */
function vf_sync_pattern( $slug, $reset = false ) {
	$files = vf_pattern_files();
	if ( ! isset( $files[ $slug ] ) ) {
		return 0;
	}
	$post = vf_synced_post( $slug );
	if ( $post && ! $reset ) {
		return $post->ID;
	}
	$pages = vf_pattern_pages();
	if ( isset( $pages[ $slug ] ) ) {
		$parts = array();
		foreach ( $pages[ $slug ] as $section ) {
			$id = vf_sync_pattern( $section ); // sections first (never reset here)
			if ( $id ) {
				$parts[] = vf_pattern_ref( $id );
			}
		}
		$content = implode( "\n\n", $parts );
	} else {
		$content = vf_pattern_markup( $slug );
	}
	if ( '' === $content ) {
		return 0;
	}
	$data = array(
		'post_type'    => 'wp_block',
		'post_status'  => 'publish',
		'post_title'   => $files[ $slug ]['title'],
		'post_excerpt' => $files[ $slug ]['description'],
		'post_content' => wp_slash( $content ),
	);
	if ( $post ) {
		$data['ID'] = $post->ID;
		$id         = wp_update_post( $data, true );
	} else {
		$id = wp_insert_post( $data, true );
	}
	if ( is_wp_error( $id ) || ! $id ) {
		return 0;
	}
	delete_post_meta( $id, 'wp_pattern_sync_status' ); // no meta = synced
	if ( taxonomy_exists( 'wp_pattern_category' ) ) {
		wp_set_object_terms( $id, 'VuloForm', 'wp_pattern_category' );
	}
	$ids          = vf_synced_ids();
	$ids[ $slug ] = (int) $id;
	update_option( 'vf_synced_patterns', $ids, false );
	return (int) $id;
}

/** All patterns: sections first, then whole pages. Returns how many exist afterwards. */
function vf_sync_all( $reset = false ) {
	$pages = vf_pattern_pages();
	$n     = 0;
	foreach ( array_keys( vf_pattern_files() ) as $slug ) {
		if ( ! isset( $pages[ $slug ] ) && vf_sync_pattern( $slug, $reset ) ) {
			$n++;
		}
	}
	foreach ( array_keys( $pages ) as $slug ) {
		if ( vf_sync_pattern( $slug, $reset ) ) {
			$n++;
		}
	}
	return $n;
}

/** Edit link of a synced pattern (block editor with Kadence). */
function vf_pattern_edit_url( $slug ) {
	$post = vf_synced_post( $slug );
	return $post ? admin_url( 'post.php?post=' . $post->ID . '&action=edit' ) : '';
}

/** Is this content built from our synced patterns? (for the full-width layout) */
function vf_uses_synced_pattern( $content ) {
	if ( false === strpos( $content, '<!-- wp:block {"ref":' ) || ! preg_match_all( '/<!-- wp:block \{"ref":(\d+)/', $content, $m ) ) {
		return false;
	}
	return (bool) array_intersect( array_map( 'intval', $m[1] ), array_map( 'intval', vf_synced_ids() ) );
}
